description:
Write checked arithmetic for `int` in `solution.c`. Each function returns `false` (and leaves `*result` alone) when the true answer does not fit in an `int`, and otherwise stores it and returns `true`:

```c
bool safe_add(int a, int b, int *result);
bool safe_subtract(int a, int b, int *result);
bool safe_multiply(int a, int b, int *result);
bool safe_abs(int a, int *result);     /* INT_MIN has no positive int */
```

The rules: test **before** doing the operation, using `INT_MAX` and `INT_MIN` from `limits.h`. No wider types (`long long`) and no compiler builtins: the point is to reason about the limits.

starter.solution.c:
#include <limits.h>
#include <stdbool.h>

bool safe_add(int a, int b, int *result)
{
    *result = a + b;
    return true;
}

bool safe_subtract(int a, int b, int *result)
{
    *result = a - b;
    return true;
}

bool safe_multiply(int a, int b, int *result)
{
    *result = a * b;
    return true;
}

bool safe_abs(int a, int *result)
{
    *result = a < 0 ? -a : a;
    return true;
}

solution.solution.c:
#include <limits.h>
#include <stdbool.h>

bool safe_add(int a, int b, int *result)
{
    if (b > 0 && a > INT_MAX - b) return false;
    if (b < 0 && a < INT_MIN - b) return false;
    *result = a + b;
    return true;
}

bool safe_subtract(int a, int b, int *result)
{
    if (b < 0 && a > INT_MAX + b) return false;
    if (b > 0 && a < INT_MIN + b) return false;
    *result = a - b;
    return true;
}

bool safe_multiply(int a, int b, int *result)
{
    if (a > 0) {
        if (b > 0) {
            if (a > INT_MAX / b) return false;
        } else if (b < INT_MIN / a) {
            return false;
        }
    } else if (a < 0) {
        if (b > 0) {
            if (a < INT_MIN / b) return false;
        } else if (b < 0 && a < INT_MAX / b) {
            return false;
        }
    }
    *result = a * b;
    return true;
}

bool safe_abs(int a, int *result)
{
    if (a == INT_MIN) return false;
    *result = a < 0 ? -a : a;
    return true;
}

unitTests:
TEST("adding") { int r = 7; CHECK(safe_add(2, 3, &r)); CHECK_EQ(r, 5); CHECK(safe_add(INT_MAX, 0, &r)); CHECK_EQ(r, INT_MAX); CHECK(safe_add(INT_MAX, INT_MIN, &r)); CHECK_EQ(r, -1); r = 7; CHECK(!safe_add(INT_MAX, 1, &r)); CHECK_EQ(r, 7); CHECK(!safe_add(INT_MIN, -1, &r)); CHECK(!safe_add(INT_MAX / 2 + 1, INT_MAX / 2 + 1, &r)); CHECK_EQ(r, 7); }
TEST("subtracting") { int r = 7; CHECK(safe_subtract(10, 3, &r)); CHECK_EQ(r, 7); CHECK(safe_subtract(-1, INT_MAX, &r)); CHECK_EQ(r, INT_MIN); r = 0; CHECK(!safe_subtract(INT_MIN, 1, &r)); CHECK(!safe_subtract(0, INT_MIN, &r)); CHECK(!safe_subtract(INT_MAX, -1, &r)); CHECK_EQ(r, 0); }
TEST("multiplying") { int r = 7; CHECK(safe_multiply(6, 7, &r)); CHECK_EQ(r, 42); CHECK(safe_multiply(-6, 7, &r)); CHECK_EQ(r, -42); CHECK(safe_multiply(-6, -7, &r)); CHECK_EQ(r, 42); CHECK(safe_multiply(0, INT_MIN, &r)); CHECK_EQ(r, 0); CHECK(safe_multiply(INT_MIN, 1, &r)); CHECK_EQ(r, INT_MIN); r = 7; CHECK(!safe_multiply(65536, 65536, &r)); CHECK(!safe_multiply(INT_MIN, -1, &r)); CHECK(!safe_multiply(-65536, 65536 / 2 + 1, &r)); CHECK(!safe_multiply(-2, INT_MIN, &r)); CHECK_EQ(r, 7); }
TEST("absolute values") { int r = 7; CHECK(safe_abs(-5, &r)); CHECK_EQ(r, 5); CHECK(safe_abs(INT_MAX, &r)); CHECK_EQ(r, INT_MAX); CHECK(safe_abs(-INT_MAX, &r)); CHECK_EQ(r, INT_MAX); r = 7; CHECK(!safe_abs(INT_MIN, &r)); CHECK_EQ(r, 7); }

